from collections import deque
out=G.copy(); vis=np.zeros(G.shape,bool); records=[]
for r in range(30):
 for c in range(30):
  if G[r,c]!=7 and not vis[r,c]:
   q=deque([(r,c)]);vis[r,c]=1;pts=[]
   while q:
    x,y=q.popleft();pts.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     xx,yy=x+dx,y+dy
     if 0<=xx<30 and 0<=yy<30 and G[xx,yy]!=7 and not vis[xx,yy]:vis[xx,yy]=1;q.append((xx,yy))
   s=set(pts)
   boundary=[]
   for x,y in pts:
    if any((x+dx,y+dy) not in s for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]):boundary.append((x,y))
   dist={p:0 for p in boundary};q=deque(boundary)
   while q:
    x,y=q.popleft()
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     p=(x+dx,y+dy)
     if p in s and p not in dist:dist[p]=dist[(x,y)]+1;q.append(p)
   mk=[(dist[p],p[0],p[1],int(G[p])) for p in pts if G[p]!=1]
   records.append((pts,dist,mk))
for i,(pts,dist,mk) in enumerate(records):
 print(i, (min(x for x,y in pts),max(x for x,y in pts),min(y for x,y in pts),max(y for x,y in pts)), 'depths',max(dist.values()),'markers',mk)

